import{_ as o,o as t,c as a,an as d}from"./chunks/framework.ByZXu0sn.js";const u=JSON.parse('{"title":"Rules for every type","description":"","frontmatter":{},"headers":[],"relativePath":"developer/extending-rules.md","filePath":"developer/extending-rules.md","lastUpdated":null}'),r={name:"developer/extending-rules.md"};function n(s,e,c,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="extending-rules" tabindex="-1">Rules for every type <a class="header-anchor" href="#extending-rules" aria-label="Permalink to &quot;Rules for every type {#extending-rules}&quot;">​</a></h1><p>Every <code>forward!</code> and <code>pullback!</code> keeps these rules, whichever page of <a href="/previews/PR883/developer/extending#extending">Writing new types</a> it follows.</p><h2 id="extending-number-types" tabindex="-1">Number types <a class="header-anchor" href="#extending-number-types" aria-label="Permalink to &quot;Number types {#extending-number-types}&quot;">​</a></h2><p><code>forward!</code> must be generic in the element type of its arguments. A dual number, a <code>Float32</code> or a tracked value can arrive in <code>v</code>, <code>s</code> or a field. So do not annotate <code>Float64</code> or build <code>0.0</code>; use <code>zero(v)</code>, <code>oftype</code> and fields with type parameters.</p><h2 id="extending-pullback-arguments" tabindex="-1">Arguments of a pullback <a class="header-anchor" href="#extending-pullback-arguments" aria-label="Permalink to &quot;Arguments of a pullback {#extending-pullback-arguments}&quot;">​</a></h2><p>In <code>pullback!</code>, <code>v</code>, <code>s</code>, <code>p</code> and <code>history</code> are the values <code>forward!</code> was given, so the values before the step. Read them, but do not write to them. Leave <code>grads</code> and the arguments after the role in <code>pullback!</code> untyped, so that the rule finds the method. A type without a <code>pullback!</code> still takes the rule when the <a href="/previews/PR883/explanation/adjoints-and-backends#adjoint-local-step">local step</a> can rebuild it.</p><h2 id="extending-pointwise-rules" tabindex="-1">Pointwise steps <a class="header-anchor" href="#extending-pointwise-rules" aria-label="Permalink to &quot;Pointwise steps {#extending-pointwise-rules}&quot;">​</a></h2><p>A pointwise modifier sets <a href="/previews/PR883/lib/public#ComposableRecurrences.blocks"><code>blocks</code></a> to <code>(1, 1)</code>, and writes entry <code>k</code> of <code>v</code> and <code>s</code> from entry <code>k</code> only, for each <code>k</code> in <code>eachindex(v)</code>.</p><ul><li><p>Loop over <code>eachindex(v)</code> and read parameters with <a href="/previews/PR883/lib/public#ComposableRecurrences.param"><code>param</code></a>, rather than broadcast; the <code>:pointwise</code> check of <code>PieceInterface</code> reports a broadcast.</p></li><li><p>Its <code>Init</code> writes <code>s[k]</code> from the parameters read at stratum <code>k</code> and time 1 and from row <code>k</code> of the history only. Without an <code>Init</code> <code>pullback!</code>, its derivative is then taken stratum by stratum, and the <code>:pointwise</code> check tests it.</p></li><li><p>Such a step runs under <a href="/previews/PR883/lib/public#ComposableRecurrences.Parallel"><code>Parallel</code></a> when it reads and writes only <code>eachindex(v)</code> entries, and allocates nothing.</p></li></ul><h2 id="extending-threads" tabindex="-1">Threads <a class="header-anchor" href="#extending-threads" aria-label="Permalink to &quot;Threads {#extending-threads}&quot;">​</a></h2><p>Under <a href="/previews/PR883/lib/public#ComposableRecurrences.Threaded"><code>Threaded</code></a> the steps of different strata can run at once. So a step writes only its own stratum&#39;s slots, and never to the type&#39;s fields. A mirror with an entry that is not a float array or a <code>Ref</code> of a number runs the reverse loop on one task; <a href="/previews/PR883/explanation/adjoints-and-backends#executors">Executors</a> says how the others are split.</p>',11)])])}const f=o(r,[["render",n]]);export{u as __pageData,f as default};
